import{_ as s,o as t,c as r,am as i}from"./chunks/framework.yj4qiWdr.js";const m=JSON.parse('{"title":"OSCP","description":"Aide-mémoire OSCP en français","frontmatter":{"title":"OSCP","description":"Aide-mémoire OSCP en français"},"headers":[],"relativePath":"oscp/index.md","filePath":"oscp/index.md"}'),o={name:"oscp/index.md"};function n(a,e,l,c,u,p){return t(),r("div",null,e[0]||(e[0]=[i('<h1 id="oscp" tabindex="-1">OSCP <a class="header-anchor" href="#oscp" aria-label="Permalink to &quot;OSCP&quot;">​</a></h1><p><strong>Offensive Security Certified Professional</strong></p><p>Retrouve une technique par thème, utilise le sommaire de chaque fiche et copie directement les commandes. La recherche est accessible avec <strong>Ctrl + K</strong>.</p><h2 id="toutes-les-rubriques" tabindex="-1">Toutes les rubriques <a class="header-anchor" href="#toutes-les-rubriques" aria-label="Permalink to &quot;Toutes les rubriques&quot;">​</a></h2><ul><li><a href="./reconnaissance"><strong>Collecte d’informations</strong></a> : Identifier les hôtes, les services et les informations accessibles.</li><li><a href="./vulnerabilites"><strong>Analyse de vulnérabilités</strong></a> : Examiner les services et leurs vulnérabilités connues.</li><li><a href="./applications-web"><strong>Applications web</strong></a> : Retrouver les outils et les vérifications des applications web.</li><li><a href="./attaques-client"><strong>Attaques côté client</strong></a> : Consulter les techniques côté poste client.</li><li><a href="./antivirus-metasploit"><strong>Évasion antivirus et Metasploit</strong></a> : Consulter les références relatives aux antivirus et à Metasploit.</li><li><a href="./mots-de-passe"><strong>Attaques par mots de passe</strong></a> : Identifier les outils et les formats liés à l’authentification.</li><li><a href="./privileges-windows"><strong>Élévation de privilèges Windows</strong></a> : Vérifier les configurations et privilèges sous Windows.</li><li><a href="./privileges-linux"><strong>Élévation de privilèges Linux</strong></a> : Vérifier les permissions et configurations sous Linux.</li><li><a href="./redirection-ports"><strong>Redirections SSH, Socat et netsh</strong></a> : Comprendre où ouvrir les ports et comment tester chaque relais.</li><li><a href="./tunneling"><strong>Ligolo-ng, Chisel et pivot</strong></a> : Reproduire un tunnel simple, un double pivot et des listeners.</li><li><a href="./ad-theorie"><strong>Théorie Active Directory</strong></a> : Comprendre les objets, tickets et droits Active Directory.</li><li><a href="./ad-enumeration"><strong>Énumération Active Directory</strong></a> : Examiner les comptes, groupes et services du domaine.</li><li><a href="./ad-techniques"><strong>Attaques Active Directory</strong></a> : Retrouver les techniques de sécurité offensive Active Directory.</li><li><a href="./ad-lateral"><strong>Mouvement latéral Active Directory</strong></a> : Consulter les protocoles et les accès distants Windows.</li><li><a href="./cloud"><strong>Infrastructures cloud</strong></a> : Contrôler les accès S3 dans un laboratoire autorisé.</li><li><a href="./rapport"><strong>Rédaction de rapports</strong></a> : Préparer les preuves, captures et rapports d’audit.</li><li><a href="./transferts"><strong>Transferts Linux et Windows</strong></a> : Choisir les commandes par sens de transfert et machine.</li><li><a href="./utilitaires"><strong>Utilitaires</strong></a> : Consulter les commandes et outils complémentaires.</li><li><a href="./methodologie"><strong>Méthodologie</strong></a> : Organiser les vérifications pendant un examen.</li><li><a href="./references"><strong>Références</strong></a> : Retrouver les liens et ressources cités par les notes.</li></ul><p>Les commandes sont classées dans leurs rubriques et présentées avec une explication courte en français. Les paramètres et valeurs isolés sont regroupés comme repères plutôt que présentés comme des commandes.</p><p><strong>À noter :</strong> la source principale ne contient pas de commandes cloud. Cette fiche est désormais enrichie avec des vérifications S3 issues de références complémentaires.</p><p>Sources : <a href="https://www.emmanuelsolis.com/oscp.html" target="_blank" rel="noreferrer">OSCP+ Cheatsheet d’Emmanuel Solis</a> et <a href="https://github.com/krovs/oscp-notes/tree/main/docs" target="_blank" rel="noreferrer">notes OSCP de krovs</a>.</p>',8)]))}const f=s(o,[["render",n]]);export{m as __pageData,f as default};
